    public static function getCompletedNotificationBody(Import $import): string
    {
        $body = 'Your Students import has completed and ' . Number::format($import->successful_rows) . ' ' . str('row')->plural($import->successful_rows) . ' imported.';

        if ($failedRowsCount = $import->getFailedRowsCount()) {
